{
  "returncode": 0,
  "output_head": "Rails.application.routes.draw do
  get "up" => "rails/health#show", as: :rails_health_check
  root to: redirect("/moderate", status: 302)

  scope "/play/:code", code: /[a-zA-Z0-9]{7}/ do
    get "/", to: "play#show", as: :play
    get "state", to: "play#state", as: :play_state, defaults: { format: :json }
    post "join", to: "play#join", as: :play_join
    post "answer", to: "play#answer", as: :play_answer
  end

  namespace :moderate do
    root "quizzes#index"
    resources :games, only: :show do
      get :state, on: :member, defaults: { format: :json }
      get :qr, on: :member
      post :advance, on: :member
    end
    resources :quizzes, except: :index do
      resources :games, only: :create
      get :preview, on: :member
      get :export, on: :member
      collection do
        get :import
        post :import, action: :create_import
      end
      resources :questions, except: %i[index show] do
        patch :move, on: :member
        patch :active, on: :member
      end
    end
  end
end
require_relative "boot"

require "rails"
require "active_model/railtie"
require "active_record/railtie"
require "action_controller/railtie"
require "action_view/railtie"
require "rails/test_unit/railtie"

Bundler.require(*Rails.groups)

module Quizzy
  class Application < Rails::Application
    config.load_defaults 8.1
    config.autoload_lib(ignore: %w[assets tasks])
  end
end
# This configuration file will be evaluated by Puma. The top-level methods that
# are invoked here are part of Puma's configuration DSL. For more information
# about methods provided by the DSL, see https://puma.io/puma/Puma/DSL.html.
#
# Puma starts a configurable number of processes (workers) and each process
# serves each request in a thread from an internal thread pool.
#
# You can control the number of workers using ENV["WEB_CONCURRENCY"]. You
# should only set this value when you want to run 2 or more workers. The
# default is already 1. You can set it to `auto` to automatically start a worker
# for each available processor.
#
# The ideal number of threads per worker depends both on how much time the
# application spends waiting for IO operations and on how much you wish to
# prioritize throughput over latency.
#
# As a rule of thumb, increasing the number of threads will increase how much
# traffic a given process can handle (throughput), but due to CRuby's
# Global VM Lock (GVL) it has diminishing returns and will degrade the
# response time (latency) of the application.
#
# The default is set to 3 threads as it's deemed a decent compromise between
# throughput and latency for the average Rails application.
#
# Any libraries that use a connection pool or another resource pool should
# be configured to provide at least as many connections as the number of
# threads. This includes Active Record's `pool` parameter in `database.yml`.
threads_count = ENV.fetch("RAILS_MAX_THREADS", 3)
threads threads_count, threads_count

# Specifies the `port` that Puma will listen on to receive requests; default is 3000.
port ENV.fetch("PORT", 3000)

# Allow puma to be restarted by `bin/rails restart` command.
plugin :tmp_restart

# Specify the PID file. Defaults to tmp/pids/server.pid in development.
# In other environments, only set the PID file if requested.
pidfile ENV["PIDFILE"] if ENV["PIDFILE"]
default: &default
  adapter: sqlite3
  max_connections: <%= ENV.fetch("RAILS_MAX_THREADS", 3) %>
  timeout: 5000

development:
  <<: *default
  database: storage/development.sqlite3

test:
  <<: *default
  database: storage/test.sqlite3

production:
  <<: *default
  database: storage/production.sqlite3
require "active_support/core_ext/integer/time"

Rails.application.configure do
  config.enable_reloading = false
  config.eager_load = true
  config.consider_all_requests_local = false

  config.assume_ssl = false
  config.force_ssl = false
  config.hosts.clear

  config.public_file_server.enabled = true
  config.public_file_server.headers = { "cache-control" => "public, max-age=#{1.year.to_i}" }
  config.logger = ActiveSupport::TaggedLogging.logger(STDOUT)
  config.log_tags = [ :request_id ]
  config.log_level = ENV.fetch("RAILS_LOG_LEVEL", "info")
  # Do not write routine poll requests to the production log.
  config.silence_healthcheck_path = %r{\A/(?:up|play/[A-Z0-9]+/state|moderate/games/\d+/state)\z}i
  config.active_record.dump_schema_after_migration = false
end
#!/bin/sh
set -eu
cd "$(dirname "$0")/.."

export RAILS_ENV=production
: "${SECRET_KEY_BASE:?Set SECRET_KEY_BASE}"
: "${QUIZZY_MODERATOR_USERNAME:?Set QUIZZY_MODERATOR_USERNAME}"
: "${QUIZZY_MODERATOR_PASSWORD:?Set QUIZZY_MODERATOR_PASSWORD}"

mkdir -p storage
bin/rails db:prepare
bin/rails assets:precompile
exec bin/rails server --binding 0.0.0.0 --port "${PORT:-3000}"
source "https://rubygems.org"

ruby "3.4.4"

gem "rails", "8.1.4"
gem "propshaft"
gem "sqlite3", "~> 2.1"
gem "puma", ">= 5.0"
gem "bootsnap", require: false
gem "rqrcode", "~> 3.2"

group :test do
  gem "minitest", "~>",
  "output_tail": "nary HTTP. Requests are jittered, unchanged phone states return `204` with no body, and counter-only updates don't replace the stage markup or QR image. Clients back off on errors and catch up when they're back online. Unconfirmed actions are not blindly retried: the client polls for the authoritative state and lets the player try again if needed.
- A player remains present for 20 seconds after their last check-in. Polling renews that lease at most once every five seconds. The open counter compares answers from present players with the number present; finished totals retain all accepted answers, even if someone has gone offline. Player HTML (including live updates) is built only from the current phase, and does not contain correctness flags or later rounds during an open question.
(() => {
  const root = document.querySelector("[data-live-game]");
  if (!root) return;

  const content = root.querySelector("[data-live-content]");
  const notice = root.querySelector("[data-live-notice]");
  const stateUrl = new URL(root.dataset.stateUrl, window.location.href);
  const interval = Number(root.dataset.pollMs);
  let ended = content.dataset.ended === "true";
  let timer, pollController, queued;
  let running = false;
  let writing = false;
  let failures = 0;
  let unconfirmed = false;

  function showNotice(message) {
    if (notice.textContent !== message) notice.textContent = message;
    notice.hidden = !message;
  }

  function apply(state) {
    if (state.html !== undefined) {
      const focused = document.activeElement;
      const wasFocused = content.contains(focused);
      const focusKey = focused?.dataset.liveFocus;
      content.innerHTML = state.html;
      content.dataset.view = state.view;
      ended = state.ended;
      if (wasFocused) {
        const target = Array.from(content.querySelectorAll("[data-live-focus]"))
          .find((element) => element.dataset.liveFocus === focusKey);
        (target || content.querySelector("[data-live-heading]"))?.focus({ preventScroll: true });
      }
      unconfirmed = false;
    }
    const counter = content.querySelector("[data-live-counter]");
    if (counter && state.counter && counter.textContent !== state.counter) {
      counter.textContent = state.counter;
    }
  }

  function schedule(delay) {
    clearTimeout(timer);
    if (!ended || queued) timer = setTimeout(sync, delay);
  }

  async function sync() {
    if (running || (ended && !queued)) return;
    running = true;
    const job = queued;
    queued = null;
    writing = Boolean(job);

    const controller = new AbortController();
    if (!job) pollController = controller;
    const deadline = setTimeout(() => controller.abort("timeout"), job ? 8000 : 5000);
    stateUrl.searchParams.set("view", content.dataset.view);

    try {
      const response = await fetch(job?.url || stateUrl, {
        method: job ? "POST" : "GET",
        body: job?.body,
        headers: { Accept: "application/json" },
        signal: controller.signal,
        cache: "no-store"
      });
      if (response.status === 404) {
        queued = null;
        ended = true;
        content.hidden = true;
        showNotice("This game is no longer available.");
        return;
      }
      if (!response.ok && !(job && [409, 422].includes(response.status))) throw new Error("Sync failed");
      if (response.status !== 204) {
        const state = await response.json();
        if (!queued) apply(state);
      }
      failures = 0;
      if (job) unconfirmed = false;
      showNotice(unconfirmed ? "Could not confirm your last action. You can try again." : "");
    } catch {
      if (controller.signal.reason !== "superseded") {
        failures += 1;
        if (job) unconfirmed = true;
        showNotice("Connection interrupted. Reconnecting…");
      }
    } finally {
      clearTimeout(deadline);
      running = writing = false;
      pollController = null;
      const delay = Math.min(8000, interval * (2 ** Math.min(failures, 4)));
      schedule(queued ? 0 : delay * (0.8 + 0.4 * Math.random()));
    }
  }

  root.addEventListener("submit", (event) => {
    const form = event.target;
    const action = form.dataset.liveAction;
    if (!action) return;
    event.preventDefault();
    if (ended || (action !== "answer" && (writing || queued))) return;
    // Serialize submissions from this page. If several choices are tapped on a
    // slow connection, send only the newest one after the in-flight choice.
    const body = new FormData(form);
    if (event.submitter?.name) body.append(event.submitter.name, event.submitter.value);
    queued = { url: form.action, body };
    clearTimeout(timer);
    pollController?.abort("superseded");
    sync();
  });

  const catchUp = () => schedule(0);
  window.addEventListener("online", catchUp);
  window.addEventListener("pageshow", catchUp);
  document.addEventListener("visibilitychange", () => { if (!document.hidden) catchUp(); });
  schedule(interval * Math.random());
})();
",
