class Quiz < ApplicationRecord
  DEFAULT_WINNERS = 3

  has_many :questions, -> { order(:position) }, dependent: :destroy, inverse_of: :quiz
  has_many :games

  validates :title, presence: true
  validates :number_of_winners, numericality: { only_integer: true, greater_than_or_equal_to: 1, less_than: 2**63 }

  def export_contents
    settings = { title: title }
    settings[:number_of_winners] = number_of_winners unless number_of_winners == DEFAULT_WINNERS

    settings.merge(
      questions: questions.map do |question|
        {
          text: question.body,
          active: question.active?,
          options: question.options.map { |option| { text: option["text"], correct: option["correct"] == true } }
        }
      end
    )
  end
end

